// Liest das automatisch gemountete ServiceAccount-Token des n8n-Pods selbst,
// um direkt (ohne Kubernetes-spezifischen n8n-Node) gegen die Kubernetes-API
// zu authentifizieren -- Standard-Technik fuer In-Cluster-API-Zugriff.
// Das RBAC dazu (nur get/patch auf die Scale-Subresource des
// ollama-Deployments) steckt in argocd/apps/workloads/ollama/templates/role-n8n-scaler.yaml.
const fs = require('fs');
const token = fs.readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/token', 'utf8').trim();
return [{ json: { token } }];

// Token frisch lesen statt den Wert von "K8s-Token lesen (Scale-up)"
// wiederzuverwenden -- der Lauf inkl. Sub-Workflow kann mehrere Minuten
// dauern, ein neuer Read ist trivial billig und vermeidet jede Annahme
// ueber die Token-Lebensdauer.
const fs = require('fs');
const token = fs.readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/token', 'utf8').trim();
return [{ json: { token } }];
